def same_chars(s0: str, s1: str) -> bool:
    from collections import Counter

    count_s0 = Counter(s0)
    count_s1 = Counter(s1)

    return count_s0.keys() == count_s1.keys() and all(count_s0[char] == count_s1[char] for char in count_s0)

